<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/functions.php';require_login();
if(current_user()['role']!=='pembeli'){set_flash('Checkout hanya dapat dilakukan oleh akun Pembeli.','warning');redirect('index.php');}
$cart=$_SESSION['cart']??[];if(!$cart){set_flash('Keranjang masih kosong.','warning');redirect('cart.php');}
$ids=array_map('intval',array_keys($cart));$res=$conn->query("SELECT id,name,price,stock FROM products WHERE id IN (".implode(',',$ids).") AND is_active=1");$items=[];$total=0;while($p=$res->fetch_assoc()){$qty=(int)$cart[$p['id']];if($qty<1||$qty>(int)$p['stock']){set_flash('Stok '.$p['name'].' tidak mencukupi.','warning');redirect('cart.php');}$p['quantity']=$qty;$p['subtotal']=$qty*$p['price'];$total+=$p['subtotal'];$items[]=$p;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$address=trim($_POST['address']??'');$phone=trim($_POST['phone']??'');if($address===''||$phone==='')$error='Alamat dan nomor telepon wajib diisi.';else{
$conn->begin_transaction();try{$uid=(int)current_user()['id'];$stmt=$conn->prepare("INSERT INTO orders(user_id,total_amount,status,shipping_address,phone) VALUES(?,?,'menunggu',?,?)");$stmt->bind_param('idss',$uid,$total,$address,$phone);$stmt->execute();$orderId=$conn->insert_id;$line=$conn->prepare("INSERT INTO order_items(order_id,product_id,product_name,price,quantity,subtotal) VALUES(?,?,?,?,?,?)");$stock=$conn->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");foreach($items as $it){$pid=(int)$it['id'];$name=$it['name'];$price=(float)$it['price'];$qty=(int)$it['quantity'];$sub=(float)$it['subtotal'];$line->bind_param('iisdid',$orderId,$pid,$name,$price,$qty,$sub);$line->execute();$stock->bind_param('iii',$qty,$pid,$qty);$stock->execute();if($stock->affected_rows!==1)throw new Exception('Stok berubah. Silakan ulangi checkout.');}$conn->commit();unset($_SESSION['cart']);set_flash('Pesanan berhasil dibuat! Nomor pesanan #'.$orderId);redirect('orders.php');}catch(Throwable $e){$conn->rollback();$error='Pesanan gagal disimpan: '.$e->getMessage();}}
}
$page_title='Checkout';require_once __DIR__.'/includes/header.php';
?>
<h1 class="section-title mb-4">Checkout</h1><div class="row g-4"><div class="col-lg-7"><div class="surface-card p-4"><h5>Informasi Pengiriman</h5><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="mb-3"><label class="form-label">Alamat lengkap</label><textarea class="form-control" name="address" rows="3" required><?= e($_POST['address']??'') ?></textarea></div><div class="mb-3"><label class="form-label">Nomor telepon</label><input class="form-control" name="phone" required value="<?= e($_POST['phone']??'') ?>"></div><button class="btn btn-primary">Buat Pesanan</button></form></div></div><div class="col-lg-5"><div class="surface-card p-4"><h5>Ringkasan</h5><?php foreach($items as $it): ?><div class="d-flex justify-content-between py-2 border-bottom"><span><?= e($it['name']) ?> × <?= (int)$it['quantity'] ?></span><strong><?= rupiah($it['subtotal']) ?></strong></div><?php endforeach; ?><div class="d-flex justify-content-between mt-3"><strong>Total</strong><strong class="price"><?= rupiah($total) ?></strong></div></div></div></div>
<?php require_once __DIR__.'/includes/footer.php'; ?>
